import * as THREE from './vendor/three.module.js';
import {xyz,normal,geography,move,delta,clamp,PLANET_RADIUS as R} from './planet.js';
export class LandProcessVisuals {
 constructor(world){this.world=world;this.overlay=false;this.revision=-1;this.meshes=[];const mesh=(geometry,material,n)=>{const m=new THREE.InstancedMesh(geometry,material,n);m.count=0;m.frustumCulled=false;world.scene.add(m);this.meshes.push(m);return m;};this.cones=mesh(new THREE.CylinderGeometry(.22,1,1,20),new THREE.MeshStandardMaterial({color:'#665b50',roughness:1}),8);this.craters=mesh(new THREE.CylinderGeometry(1,1,.04,20),new THREE.MeshStandardMaterial({color:'#241d1b'}),8);this.lava=mesh(new THREE.SphereGeometry(1,10,5),new THREE.MeshBasicMaterial(),48);this.water=mesh(new THREE.SphereGeometry(1,16,6),new THREE.MeshStandardMaterial({color:'#69adc1',transparent:true,opacity:.58,roughness:.24,metalness:.3,depthWrite:false}),512);
  this.rivers=this.lines(512*8*2,'#76c6d7',.8);this.faults=this.lines(32*8*2,'#e7a974',.7);this.rings=this.lines(12*64*2,'#ffc59a',.65);this.plume=mesh(new THREE.SphereGeometry(1,6,4),new THREE.MeshBasicMaterial({color:'#a19b91',transparent:true,opacity:.2,depthWrite:false}),64);
  this.bytes=new Uint16Array(512*4);this.texture=new THREE.DataTexture(this.bytes,32,16,THREE.RGBAFormat,THREE.HalfFloatType);this.texture.magFilter=this.texture.minFilter=THREE.LinearFilter;this.texture.wrapS=THREE.RepeatWrapping;
  const mat=world.land.material,previous=mat.onBeforeCompile;mat.onBeforeCompile=s=>{previous(s);s.uniforms.uRelief={value:this.texture};s.vertexShader='uniform sampler2D uRelief;\n'+s.vertexShader.replace('vSurface=normalize(position);',`vSurface=normalize(position);vec2 reliefUV=vec2(atan(vSurface.x,vSurface.z)/6.28318530718+.5,vSurface.y*.5+.5);float displacement=texture2D(uRelief,reliefUV).r;float baseRadius=length(position);transformed=vSurface*(baseRadius>=42.?max(42.03,baseRadius+displacement):min(41.97,baseRadius+displacement));`);s.fragmentShader='uniform sampler2D uRelief;\n'+s.fragmentShader.replace('float snow=smoothstep(.75,.94,abs(vSurface.y));','float snow=clamp(texture2D(uRelief,vec2(atan(vSurface.x,vSurface.z)/6.28318530718+.5,vSurface.y*.5+.5)).g*2.,0.,1.);');};mat.customProgramCacheKey=()=> 'vespera-relief-1';mat.needsUpdate=true;world.land.geometry.boundingSphere=new THREE.Sphere(new THREE.Vector3(),R+8);
 }
 lines(count,color,opacity){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(count*3),3));g.setDrawRange(0,0);const m=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color,transparent:true,opacity,depthWrite:false}));m.frustumCulled=false;this.world.scene.add(m);return m;}
 segment(mesh,index,a,b,lift=.045){const arr=mesh.geometry.attributes.position.array;for(const [k,p]of[a,b].entries()){const v=xyz(p.x,p.z,this.world.sim.groundHeight(p.x,p.z)+lift);arr.set([v.x,v.y,v.z],index*3+k*3);}return index+2;}
 finishLine(mesh,count){mesh.geometry.setDrawRange(0,count);mesh.geometry.attributes.position.needsUpdate=true;}
 update(time){const w=this.world,s=w.sim,g=s.geology,h=s.hydrology;if(!g||!h)return;
  if(this.source!==s.worldSeed||this.revision!==g.revision){this.source=s.worldSeed;this.revision=g.revision;for(let i=0;i<512;i++){this.bytes[i*4]=THREE.DataUtils.toHalfFloat(g.cells[i].uplift+g.cells[i].erosion);this.bytes[i*4+1]=THREE.DataUtils.toHalfFloat(Math.min(8,h.snow[i]));}this.texture.needsUpdate=true;
   for(const river of w.riverBeds){const pos=river.geometry.attributes.position;river.userData.sites.forEach((site,i)=>{const flow=h.flow[s.environment.index(site.x,site.z)],p=move(site.x,site.z,site.side*clamp(.15+flow*20,.15,.65),0),v=xyz(p.x,p.z,s.groundHeight(site.x,site.z)+.06);pos.setXYZ(i,v.x,v.y,v.z);});pos.needsUpdate=true;river.geometry.computeBoundingSphere();}
   let n=0;for(const v of g.vents){const base=Math.max(.03,geography(v.x,v.z).height+g.offset(v.x,v.z));w.place(this.cones,n,v.x,v.z,base+v.cone*.5,v.radius,v.cone,v.radius);w.place(this.craters,n++,v.x,v.z,base+v.cone+.02,v.radius*.22,1,v.radius*.22,v.erupting?'#f76a35':'#241d1b');}w.finish(this.cones,n);w.finish(this.craters,n);
   n=0;for(const l of g.lava){const c=new THREE.Color('#2c2928').lerp(new THREE.Color('#ff762b'),clamp(l.heat,0,1));w.place(this.lava,n++,l.x,l.z,s.groundHeight(l.x,l.z)+.06,l.radius,.055,l.radius,c);}w.finish(this.lava,n);
   n=0;for(let i=0;i<512;i++)if(h.flood[i]>.015){const p=s.environment.geo[i],depth=h.flood[i],r=Math.min(6,depth*6);w.place(this.water,n++,p.x,p.z,s.groundHeight(p.x,p.z)+.04,r,.04+Math.min(.5,depth*.2),r);}w.finish(this.water,n);
   n=0;for(let i=0;i<512;i++){const j=h.downstream[i];if(i===j||h.flow[i]<.00003)continue;const a=s.environment.geo[i],b=s.environment.geo[j],d=delta(a,b);for(let k=0;k<8;k++)n=this.segment(this.rivers,n,move(a.x,a.z,d.x*k/8,d.z*k/8),move(a.x,a.z,d.x*(k+1)/8,d.z*(k+1)/8));}this.finishLine(this.rivers,n);
   n=0;for(const f of g.faults){const a=s.environment.geo[f.i],b=s.environment.geo[f.j],d=delta(a,b);for(let k=0;k<8;k++)n=this.segment(this.faults,n,move(a.x,a.z,d.x*k/8,d.z*k/8),move(a.x,a.z,d.x*(k+1)/8,d.z*(k+1)/8),.08);}this.finishLine(this.faults,n);
  }
  this.faults.visible=this.overlay;let n=0;for(const q of g.quakes){const age=time-q.time;if(age<0||age>12)continue;const r=.4+age*.65;for(let k=0;k<64;k++)n=this.segment(this.rings,n,move(q.x,q.z,Math.sin(k/64*Math.PI*2)*r,Math.cos(k/64*Math.PI*2)*r),move(q.x,q.z,Math.sin((k+1)/64*Math.PI*2)*r,Math.cos((k+1)/64*Math.PI*2)*r),.1);}this.finishLine(this.rings,n);
  n=0;if(w.qualityTier<2)for(const v of g.vents)if(v.erupting){const wind=s.environment.cells[s.environment.index(v.x,v.z)];for(let k=0;k<24&&n<64;k++){const age=(time*.4+k*.31)%7,p=move(v.x,v.z,wind.east*age*.09,wind.north*age*.09);w.place(this.plume,n++,p.x,p.z,s.groundHeight(v.x,v.z)+age+.2,.15+age*.16,.2+age*.22,.15+age*.16);}}w.finish(this.plume,n);
 }
}
